--
-- Table structure for table `sensor_log`
--

CREATE TABLE `sensor_log` (
  `id` int NOT NULL,
  `jarak_cm` float NOT NULL COMMENT 'Jarak pembacaan sensor HC-SR04 (cm)',
  `gas_adc` int NOT NULL COMMENT 'Nilai analog mentah sensor MQ-135 (0 - 4095)',
  `status_penuh` tinyint(1) NOT NULL COMMENT '1 = Penuh (jarak <= 10 cm), 0 = Normal',
  `status_bau` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status_tutup` tinyint(1) NOT NULL DEFAULT '0',
  `dibuat_pada` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Waktu pencatatan rekaman di server'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

